// Code Node - Preparar Post HTML + Payload Telegram (sendDocument)
// VERSÃO 2.0 - Preview Melhorado com formatação visual aprimorada

const draft = $json;

// Variáveis de controle da sessão
const currentNumber = draft.review_order || 1;
const totalPosts = draft.total_in_session || 1;

// Define o chat_id
const chatId = "8375309778";

// Configuração de tier com emojis
let tierEmoji, tierLabel, tierColor;
switch(draft.tier) {
  case 'TIER_1':
    tierEmoji = '🔴';
    tierLabel = 'URGENTE';
    tierColor = '#dc3545';
    break;
  case 'TIER_2':
    tierEmoji = '🟡';
    tierLabel = 'NORMAL';
    tierColor = '#ffc107';
    break;
  case 'TIER_3':
    tierEmoji = '🟢';
    tierLabel = 'BAIXA';
    tierColor = '#28a745';
    break;
  default:
    tierEmoji = '⚪';
    tierLabel = 'N/A';
    tierColor = '#6c757d';
}

// Formata a data
const createdDate = draft.created_at 
  ? new Date(draft.created_at).toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit', 
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  : 'Data não disponível';

const originalDate = draft.original_date
  ? new Date(draft.original_date).toLocaleDateString('pt-BR')
  : null;

// Formata categorias e tags
const categories = Array.isArray(draft.categories) 
  ? draft.categories.join(', ') 
  : (draft.categories || 'Geral');

const tags = Array.isArray(draft.tags) 
  ? draft.tags.slice(0, 5).join(', ')
  : (draft.tags || 'Sem tags');

// Conteúdo do post
const postContent = draft.content_html || draft.content_markdown || 'Conteúdo não disponível';

// Extrai preview do texto (primeiros 300 caracteres sem HTML)
const plainText = postContent.replace(/<[^>]*>/g, '').replace(/\n+/g, ' ').trim();
const previewText = plainText.length > 300 
  ? plainText.substring(0, 300) + '...'
  : plainText;

// Calcula tempo de leitura se não existir
const wordCount = draft.word_count || plainText.split(/\s+/).length;
const readingTime = draft.reading_time_minutes || Math.ceil(wordCount / 200);

// Fonte original formatada
const sourceInfo = draft.original_source || 'Fonte não informada';

// ============================================
// CAPTION MELHORADO - VISUAL E INFORMATIVO
// ============================================
const caption = `📰 *ARTIGO PARA REVISÃO*
━━━━━━━━━━━━━━━━━━━━━

📌 *Título:*
${draft.title || 'Sem título'}

📊 *Metadados:*
├─ Prioridade: ${tierEmoji} ${tierLabel}
├─ Categoria: ${categories}
├─ Tags: ${tags}
├─ Palavras: ${wordCount}
└─ Leitura: ${readingTime} min

📝 *Preview:*
"${previewText}"

🔗 *Fonte:* ${sourceInfo}
📅 *Data:* ${originalDate || createdDate}

━━━━━━━━━━━━━━━━━━━━━
📄 _Abra o HTML anexo para ver o artigo completo_
🔢 Post ${currentNumber} de ${totalPosts}`;

// ============================================
// BOTÕES INLINE MELHORADOS
// ============================================
const inlineKeyboard = [
  [
    { text: '✅ Aprovar', callback_data: `approve_${draft.id}` },
    { text: '📝 Revisar', callback_data: `edit_${draft.id}` },
    { text: '❌ Rejeitar', callback_data: `reject_${draft.id}` }
  ]
];

// ============================================
// TEMPLATE HTML
// ============================================
const htmlContent = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${draft.title || 'Post para Revisão'}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.6; color: #333; background: #f5f5f5; padding: 16px; }
    .container { max-width: 800px; margin: 0 auto; background: white; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); overflow: hidden; }
    .header { background: ${tierColor}; color: white; padding: 20px; }
    .header-badge { display: inline-block; background: rgba(255,255,255,0.2); padding: 4px 12px; border-radius: 20px; font-size: 14px; margin-bottom: 12px; }
    .header h1 { font-size: 22px; font-weight: 600; line-height: 1.3; }
    .meta-section { background: #f8f9fa; padding: 16px 20px; border-bottom: 1px solid #e9ecef; }
    .meta-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
    .meta-item { font-size: 14px; }
    .meta-label { color: #666; font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
    .meta-value { font-weight: 500; color: #333; }
    .categories { padding: 12px 20px; background: #fff; border-bottom: 1px solid #e9ecef; }
    .category-tag { display: inline-block; background: #e9ecef; color: #495057; padding: 4px 10px; border-radius: 4px; font-size: 13px; margin: 2px 4px 2px 0; }
    .excerpt { padding: 20px; background: #fffbeb; border-left: 4px solid #f59e0b; margin: 20px; border-radius: 0 8px 8px 0; }
    .excerpt-label { font-size: 12px; text-transform: uppercase; color: #92400e; margin-bottom: 8px; font-weight: 600; }
    .excerpt-text { color: #78350f; font-style: italic; }
    .content { padding: 24px 20px; }
    .content-label { font-size: 12px; text-transform: uppercase; color: #666; margin-bottom: 16px; font-weight: 600; letter-spacing: 0.5px; }
    .content-body { font-size: 16px; line-height: 1.8; }
    .content-body h2 { font-size: 20px; border-bottom: 2px solid #e9ecef; padding-bottom: 8px; margin-top: 24px; margin-bottom: 12px; }
    .content-body h3 { font-size: 17px; margin-top: 20px; margin-bottom: 10px; }
    .content-body p { margin-bottom: 16px; }
    .content-body ul, .content-body ol { margin: 16px 0; padding-left: 24px; }
    .content-body li { margin-bottom: 8px; }
    .footer { background: #f8f9fa; padding: 16px 20px; font-size: 12px; color: #666; text-align: center; border-top: 1px solid #e9ecef; }
    .footer-id { font-family: monospace; background: #e9ecef; padding: 2px 8px; border-radius: 4px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div class="header-badge">${tierEmoji} ${tierLabel}</div>
      <h1>${draft.title || 'Título não disponível'}</h1>
    </div>
    <div class="meta-section">
      <div class="meta-grid">
        <div class="meta-item"><div class="meta-label">Palavras</div><div class="meta-value">${wordCount}</div></div>
        <div class="meta-item"><div class="meta-label">Leitura</div><div class="meta-value">${readingTime} min</div></div>
        <div class="meta-item"><div class="meta-label">Data Original</div><div class="meta-value">${originalDate || createdDate}</div></div>
        <div class="meta-item"><div class="meta-label">Fonte</div><div class="meta-value">${sourceInfo}</div></div>
      </div>
    </div>
    <div class="categories">
      <span class="meta-label">Categoria: </span><span class="category-tag">${categories}</span>
      ${tags !== 'Sem tags' ? `<br><span class="meta-label" style="margin-top:8px;display:inline-block;">Tags: </span>${tags.split(', ').map(t => '<span class="category-tag">' + t.trim() + '</span>').join('')}` : ''}
    </div>
    ${draft.excerpt ? `<div class="excerpt"><div class="excerpt-label">📋 Resumo</div><div class="excerpt-text">${draft.excerpt}</div></div>` : ''}
    <div class="content">
      <div class="content-label">📄 Conteúdo Completo</div>
      <div class="content-body">${postContent}</div>
    </div>
    <div class="footer">Post ID: <span class="footer-id">${draft.id || 'N/A'}</span>${draft.slug ? ` | Slug: <span class="footer-id">${draft.slug}</span>` : ''}</div>
  </div>
</body>
</html>`;

// ============================================
// GERA O ARQUIVO COMO BINARY
// ============================================
const fileName = `post_${draft.tier || 'draft'}_${(draft.id || 'unknown').substring(0, 8)}.html`;
const binaryData = Buffer.from(htmlContent, 'utf-8');

// ============================================
// RETORNA DADOS + BINARY
// ============================================
return {
  json: {
    chat_id: chatId,
    caption: caption,
    parse_mode: "Markdown",
    reply_markup: JSON.stringify({ inline_keyboard: inlineKeyboard }),
    draft_id: draft.id,
    draft_title: draft.title,
    file_name: fileName
  },
  binary: {
    document: {
      data: binaryData.toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
};

// Code Node - Extrair Message ID da Resposta do Telegram
// Após o HTTP Request sendDocument

// A resposta do Telegram vem em $json
const telegramResponse = $json;

// Verifica se a resposta foi bem-sucedida
if (!telegramResponse.ok || !telegramResponse.result) {
  throw new Error('Resposta do Telegram inválida: ' + JSON.stringify(telegramResponse));
}

// Extrai o message_id da resposta
// Para sendDocument, o message_id vem em result.message_id
const messageId = telegramResponse.result.message_id;

// Pega o draft_id do Code Node que preparou o payload
// IMPORTANTE: Usamos $('Nome do Node') para acessar dados de nodes anteriores
const draftId = $('PREPARAR TELEGRAM').item.json.draft_id;

if (!draftId) {
  throw new Error('draft_id não encontrado no node anterior');
}

// Timestamp de quando a mensagem foi enviada com sucesso
const sentAt = new Date().toISOString();

// Retorna objeto limpo para o Update a row1
return {
  post_id: draftId,               // ID do post para o filtro WHERE
  telegram_message_id: messageId, // ID da mensagem no Telegram (bigint)
  review_started_at: sentAt       // Timestamp do envio
};

// Início do dia em Brasília (UTC-3)
const startOfDayBrasilia = new Date();
startOfDayBrasilia.setUTCHours(0, 0, 0, 0); // 00:00 Brasília = 03:00 UTC

// Fim do dia em Brasília
const endOfDayBrasilia = new Date(startOfDayBrasilia);
endOfDayBrasilia.setUTCHours(26, 59, 59, 999); // 23:59 Brasília = 02:59 UTC+1

return {
  dateStart: startOfDayBrasilia.toISOString(),
  dateEnd: endOfDayBrasilia.toISOString()
};

// Code Node - Criar Sessão e Preparar Items para Update
// Este node recebe todos os drafts do Supabase Select anterior

const allDrafts = $input.all();

if (allDrafts.length === 0) {
  throw new Error('Nenhum draft encontrado para revisão');
}

// Cria um ID único para esta sessão de revisão
// O formato: review_timestamp_randomstring garante unicidade absoluta
const sessionId = `review_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Conta total de posts nesta sessão
const totalPosts = allDrafts.length;

// Timestamp atual que será usado para marcar quando esta sessão começou
const sessionStartTime = new Date().toISOString();

// Transforma cada draft em um item enriquecido com dados de sessão
return allDrafts.map((item, index) => {
  const draft = item.json;

  return {
    // Mantém todas as propriedades originais do draft
    ...draft,

    // Adiciona as propriedades de sessão usando os nomes CORRETOS das suas colunas
    review_session_id: sessionId,           // Nome correto da sua coluna
    review_order: index + 1,                 // Posição: 1, 2, 3, etc
    total_in_session: totalPosts,           // Nova coluna que você vai criar
    review_started_at: sessionStartTime     // Marca quando a sessão começou
  };
});
